package com.loanops.fincompass.opportunity;
import com.loanops.fincompass.matching.MatchRecords.Run;import com.loanops.fincompass.matching.MatchingModels.Status;import com.loanops.fincompass.simulation.ScenarioRecords.Scenario;import com.loanops.fincompass.twin.TwinModels.*;import java.math.BigDecimal;import java.util.*;import static com.loanops.fincompass.opportunity.OpportunityModels.*;
public final class OpportunityEngine {
 public List<Draft> evaluate(Snapshot current,List<Snapshot> history,Scenario latestHome,List<Run> matches,Policy policy){if(current==null||history==null||matches==null||policy==null)throw new IllegalArgumentException("Opportunity inputs required");List<Draft> out=new ArrayList<>();
  if(!"COMPLETE".equals(current.status())||current.result().warnings().stream().anyMatch(w->w.contains("STALE")||w.contains("PARTIAL")))return List.of();
  if(latestHome!=null&&latestHome.homeResult()!=null){var metrics=latestHome.homeResult().after();BigDecimal cash=value(metrics,"MONTHLY_FREE_CASHFLOW");BigDecimal emergency=value(metrics,"EMERGENCY_FUND_MONTHS");BigDecimal burden=value(metrics,"DEBT_SERVICE_BURDEN");
   if(cash!=null&&cash.signum()<0)out.add(draft(Type.LIQUIDITY_RISK,current,latestHome,new Evidence("MONTHLY_FREE_CASHFLOW",cash,BigDecimal.ZERO,"KRW_PER_MONTH",List.of()),List.of("SIMULATED_POST_PURCHASE_NEGATIVE_CASHFLOW")));
   else if(emergency!=null&&emergency.compareTo(policy.emergencyFundMonths())<0)out.add(draft(Type.LIQUIDITY_RISK,current,latestHome,new Evidence("EMERGENCY_FUND_MONTHS",emergency,policy.emergencyFundMonths(),"MONTHS",List.of()),List.of()));
   if(burden!=null&&burden.compareTo(policy.debtBurden())>0)out.add(draft(Type.DEBT_BURDEN_WARNING,current,latestHome,new Evidence("DEBT_SERVICE_BURDEN",burden,policy.debtBurden(),"FRACTION",List.of()),List.of("ANALYTICAL_THRESHOLD_NOT_REGULATORY_DSR")));
  } else {BigDecimal cash=value(current.result().metrics(),"MONTHLY_FREE_CASHFLOW"),emergency=value(current.result().metrics(),"EMERGENCY_FUND_MONTHS"),burden=value(current.result().metrics(),"DEBT_SERVICE_BURDEN");if(cash!=null&&cash.signum()<0)out.add(draft(Type.LIQUIDITY_RISK,current,null,new Evidence("MONTHLY_FREE_CASHFLOW",cash,BigDecimal.ZERO,"KRW_PER_MONTH",List.of()),List.of()));else if(emergency!=null&&emergency.compareTo(policy.emergencyFundMonths())<0)out.add(draft(Type.LIQUIDITY_RISK,current,null,new Evidence("EMERGENCY_FUND_MONTHS",emergency,policy.emergencyFundMonths(),"MONTHS",List.of()),List.of()));if(burden!=null&&burden.compareTo(policy.debtBurden())>0)out.add(draft(Type.DEBT_BURDEN_WARNING,current,null,new Evidence("DEBT_SERVICE_BURDEN",burden,policy.debtBurden(),"FRACTION",List.of()),List.of("ANALYTICAL_THRESHOLD_NOT_REGULATORY_DSR")));}
  List<Snapshot> usable=history.stream().filter(s->"COMPLETE".equals(s.status())).toList();if(usable.size()>1){Snapshot previous=usable.get(usable.size()-2);BigDecimal nowIncome=current.result().verifiedAnnualIncome(),oldIncome=previous.result().verifiedAnnualIncome(),nowDebt=value(current.result().metrics(),"TOTAL_LIABILITIES"),oldDebt=value(previous.result().metrics(),"TOTAL_LIABILITIES");if(nowIncome!=null&&oldIncome!=null&&nowIncome.compareTo(oldIncome)>0||nowDebt!=null&&oldDebt!=null&&nowDebt.compareTo(oldDebt)<0)out.add(new Draft(Type.RATE_REVIEW,current.financialSnapshotId(),null,null,new Evidence("VALIDATED_FINANCIAL_IMPROVEMENT",BigDecimal.ONE,BigDecimal.ONE,"BOOLEAN",List.of()),List.of("HISTORICAL_VALIDATED_CHANGE_REVIEW")));}
  BigDecimal existingRate=current.input().facts().stream().filter(f->"EXISTING_LOAN_ANNUAL_RATE".equals(f.kind())).map(Fact::value).findFirst().orElse(null);if(existingRate!=null){for(Run run:matches){var comparable=run.candidates().stream().filter(c->c.status()==Status.MATCHED_FOR_REVIEW&&c.simulationAnnualRate()!=null&&existingRate.subtract(c.simulationAnnualRate()).compareTo(policy.refinancingRateGap())>=0).toList();if(!comparable.isEmpty()){out.add(new Draft(Type.REFINANCING_REVIEW,current.financialSnapshotId(),run.scenarioId(),run.matchRunId(),new Evidence("ANNUAL_RATE_GAP",existingRate.subtract(comparable.getFirst().simulationAnnualRate()),policy.refinancingRateGap(),"FRACTION",comparable.stream().map(c->c.product().productTermId()).toList()),List.of("REVIEW_REFINANCING_OPTIONS_NOT_ADVICE")));break;}}}
  return List.copyOf(out);
 }
 private Draft draft(Type type,Snapshot snapshot,Scenario scenario,Evidence evidence,List<String>warnings){return new Draft(type,snapshot.financialSnapshotId(),scenario==null?null:scenario.scenarioId(),null,evidence,warnings);}
 private BigDecimal value(Map<String,Metric> metrics,String name){Metric m=metrics.get(name);return m!=null&&m.availability()==Availability.AVAILABLE?m.value():null;}
}
